 const loadHistory=async()=>{if(!project)return;setBusy(true);try{setRevisions(await api<any[]>(`${ROOT}/resumes/${encodeURIComponent(project.id)}/revisions`))}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
